<template><div class="sf-day-strip" role="tablist" :aria-label="label"><button v-for="(day,index) in days" :key="day.value" type="button" role="tab" :aria-selected="value===day.value?'true':'false'" :aria-label="day.label+' · '+day.theme" :tabindex="value===day.value?0:-1" @click.stop="select(day)" @keydown="navigate($event,index)"><span>{{ day.label }}</span><div><img :src="value===day.value&&(day.selectedIcon||day.icon)?(day.selectedIcon||day.icon):day.icon" alt="" data-source-asset="true"></div></button></div></template>
<script>
export default {name:'SfDayStrip',props:{days:{type:Array,required:true},value:[String,Number],label:{type:String,default:'Upcoming training days'}},methods:{select(day){this.$emit('input',day.value);this.$emit('change',day)},navigate(event,index){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();event.stopPropagation();const next=event.key==='Home'?0:event.key==='End'?this.days.length-1:(index+(event.key==='ArrowRight'?1:-1)+this.days.length)%this.days.length;this.select(this.days[next]);this.$nextTick(()=>this.$el.querySelectorAll('button')[next].focus())}}}
</script>
